#!/usr/bin/env -S uv run --script
# /// script
# requires-python = ">=3.14"
# dependencies = []
# ///
"""Regenerate the archive fixtures used by tests/cli.rs.

The fixtures are built independently of ziptree's own crates: Python's
standard library writes zip, tar, gz, bz2, xz and zst; the `lz4` and `7z`
command-line tools write .tar.lz4 and .7z.

requires-python >= 3.14: `compression.zstd` entered the standard library in 3.14.
"""

import argparse
import bz2
import gzip
import io
import lzma
import os
import subprocess
import tarfile
import tempfile
import zipfile
from pathlib import Path

from compression import zstd

FIXTURE_DIR = Path(__file__).resolve().parent

# Fixed timestamps keep the generated bytes stable across runs.
ZIP_DATE_TIME = (2020, 1, 1, 0, 0, 0)
FIXED_MTIME = 1577836800  # 2020-01-01T00:00:00Z
GZIP_MTIME = 0
ZSTD_LEVEL = 19

DIR_MODE = 0o755
FILE_MODE = 0o644

ZIP_UTF8_FLAG = 0x800

SIZE_ONE = 1
SIZE_MEDIUM = 1536
SIZE_BIG = 1_234_567

# (path, content) - a path ending in "/" is a directory.
SAMPLE_ENTRIES = [
    ("docs/", None),
    ("docs/sub/", None),
    ("docs/readme.txt", b"x" * SIZE_ONE),
    ("docs/empty.txt", b""),
    ("docs/sub/medium.bin", bytes(SIZE_MEDIUM)),
    (".hidden", b"hide"),
    (".git/", None),
    (".git/config", b"cfg"),
]
# Left out of the uncompressed sample.tar, where it would cost its full size.
BIG_ENTRIES = [
    ("big.bin", bytes(SIZE_BIG)),
]
MACOSX_ENTRIES = [
    ("__MACOSX/", None),
    ("__MACOSX/._big.bin", b"rf"),
]

UTF8_ENTRIES = [
    ("café/", None),
    ("café/naïve.txt", b"x"),
]
# Same name, composed (NFC) and decomposed (NFD).
NFC_NAME = "café.txt"
NFD_NAME = "café.txt"
NORMALIZATION_ENTRIES = [
    (NFC_NAME, b"nfc"),
    (NFD_NAME, b"nfd"),
]
# CP437 byte 0x82 is "é".
CP437_NAME = b"caf\x82.txt"
LATIN1_NAME = "café.txt"
SEVENZ_UNICODE_ENTRIES = [
    ("日本語/", None),
    ("日本語/🎉.txt", b"x"),
]


def write_zip(path, entries):
    with zipfile.ZipFile(path, "w", compression=zipfile.ZIP_DEFLATED) as z:
        for name, content in entries:
            info = zipfile.ZipInfo(name, date_time=ZIP_DATE_TIME)
            info.external_attr = (DIR_MODE if content is None else FILE_MODE) << 16
            info.compress_type = zipfile.ZIP_DEFLATED
            z.writestr(info, b"" if content is None else content)


def write_cp437_zip(path):
    """Write a zip whose entry name is CP437 bytes without the UTF-8 flag.

    zipfile always flags non-ASCII names as UTF-8, so write an ASCII
    placeholder of the same length and patch the name bytes in place.
    """
    placeholder = b"cafX.txt"
    assert len(placeholder) == len(CP437_NAME)
    buf = io.BytesIO()
    write_zip(buf, [(placeholder.decode("ascii"), b"x")])
    data = buf.getvalue()
    assert data.count(placeholder) == 2  # local header + central directory
    path.write_bytes(data.replace(placeholder, CP437_NAME))
    with zipfile.ZipFile(path) as z:
        assert not z.infolist()[0].flag_bits & ZIP_UTF8_FLAG


def tar_bytes(entries, tar_format=tarfile.PAX_FORMAT, encoding="utf-8"):
    buf = io.BytesIO()
    with tarfile.open(fileobj=buf, mode="w", format=tar_format, encoding=encoding) as t:
        for name, content in entries:
            info = tarfile.TarInfo(name.rstrip("/"))
            info.mtime = FIXED_MTIME
            if content is None:
                info.type = tarfile.DIRTYPE
                info.mode = DIR_MODE
                t.addfile(info)
            else:
                info.mode = FILE_MODE
                info.size = len(content)
                t.addfile(info, io.BytesIO(content))
    return buf.getvalue()


def write_lz4(path, data):
    subprocess.run(["lz4", "-q", "-f", "-", str(path)], input=data, check=True)


def write_7z(path, entries):
    """Lay the entries out on disk and archive them with the 7z CLI."""
    path.unlink(missing_ok=True)
    with tempfile.TemporaryDirectory() as tmp:
        root = Path(tmp)
        for name, content in entries:
            target = root / name
            if content is None:
                target.mkdir(parents=True, exist_ok=True)
            else:
                target.parent.mkdir(parents=True, exist_ok=True)
                target.write_bytes(content)
        for p in root.rglob("*"):
            os.utime(p, (FIXED_MTIME, FIXED_MTIME))
        top_level = sorted({name.split("/")[0] for name, _ in entries})
        subprocess.run(
            ["7z", "a", "-t7z", "-bd", "-bso0", str(path), *top_level],
            cwd=root,
            check=True,
        )


def make_fixtures(out_dir=FIXTURE_DIR):
    out_dir = Path(out_dir)
    write_zip(out_dir / "sample.zip", SAMPLE_ENTRIES + BIG_ENTRIES + MACOSX_ENTRIES)
    write_7z(out_dir / "sample.7z", SAMPLE_ENTRIES + BIG_ENTRIES)

    (out_dir / "sample.tar").write_bytes(tar_bytes(SAMPLE_ENTRIES))
    plain = tar_bytes(SAMPLE_ENTRIES + BIG_ENTRIES)
    (out_dir / "sample.tar.gz").write_bytes(gzip.compress(plain, mtime=GZIP_MTIME))
    (out_dir / "sample.tar.bz2").write_bytes(bz2.compress(plain))
    (out_dir / "sample.tar.xz").write_bytes(lzma.compress(plain, format=lzma.FORMAT_XZ))
    (out_dir / "sample.tar.zst").write_bytes(zstd.compress(plain, level=ZSTD_LEVEL))
    write_lz4(out_dir / "sample.tar.lz4", plain)

    write_zip(out_dir / "enc-utf8.zip", UTF8_ENTRIES)
    write_cp437_zip(out_dir / "enc-cp437.zip")
    write_zip(out_dir / "enc-nfd.zip", NORMALIZATION_ENTRIES)
    (out_dir / "enc-utf8.tar").write_bytes(tar_bytes(UTF8_ENTRIES))
    (out_dir / "enc-latin1.tar").write_bytes(
        tar_bytes([(LATIN1_NAME, b"x")], tarfile.GNU_FORMAT, "latin-1")
    )
    (out_dir / "enc-nfd.tar").write_bytes(tar_bytes(NORMALIZATION_ENTRIES))
    write_7z(out_dir / "enc-unicode.7z", SEVENZ_UNICODE_ENTRIES)


def main():
    parser = argparse.ArgumentParser(description=__doc__.splitlines()[0])
    parser.add_argument(
        "-o",
        "--out-dir",
        default=FIXTURE_DIR,
        help="output directory (default: %(default)s)",
    )
    make_fixtures(parser.parse_args().out_dir)


if __name__ == "__main__":
    main()
